  /**
   * Test AttributeUpdateNotificationMsg {@link AttributeUpdateNotificationMsg#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link AttributeUpdateNotificationMsg#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test AttributeUpdateNotificationMsg parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"AttributeUpdateNotificationMsg AttributeUpdateNotificationMsg.parseDelimitedFrom(InputStream)"})
  void testAttributeUpdateNotificationMsgParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    AttributeUpdateNotificationMsg actualParseDelimitedFromResult = AttributeUpdateNotificationMsg
        .parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSharedDeletedCount());
    assertEquals(0, actualParseDelimitedFromResult.getSharedUpdatedCount());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getSharedDeletedList().isEmpty());
    List<TsKvProto> sharedUpdatedList = actualParseDelimitedFromResult.getSharedUpdatedList();
    assertTrue(sharedUpdatedList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(sharedUpdatedList, actualParseDelimitedFromResult.getSharedUpdatedOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

