  /**
   * Test AttributeValueProto {@link AttributeValueProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link AttributeValueProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test AttributeValueProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"AttributeValueProto AttributeValueProto.parseDelimitedFrom(InputStream)"})
  void testAttributeValueProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    AttributeValueProto actualParseDelimitedFromResult = AttributeValueProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getJsonV());
    assertEquals("", actualParseDelimitedFromResult.getKey());
    assertEquals("", actualParseDelimitedFromResult.getStringV());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getTypeValue());
    assertEquals(0.0d, actualParseDelimitedFromResult.getDoubleV());
    assertEquals(0L, actualParseDelimitedFromResult.getLastUpdateTs());
    assertEquals(0L, actualParseDelimitedFromResult.getLongV());
    assertEquals(0L, actualParseDelimitedFromResult.getVersion());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(KeyValueType.BOOLEAN_V, actualParseDelimitedFromResult.getType());
    assertFalse(actualParseDelimitedFromResult.getBoolV());
    assertFalse(actualParseDelimitedFromResult.getHasV());
    assertFalse(actualParseDelimitedFromResult.hasKey());
    assertFalse(actualParseDelimitedFromResult.hasVersion());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

