  /**
   * Test DeviceAttributesEventMsgProto {@link DeviceAttributesEventMsgProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link DeviceAttributesEventMsgProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test DeviceAttributesEventMsgProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"DeviceAttributesEventMsgProto DeviceAttributesEventMsgProto.parseDelimitedFrom(InputStream)"})
  void testDeviceAttributesEventMsgProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    DeviceAttributesEventMsgProto actualParseDelimitedFromResult = DeviceAttributesEventMsgProto
        .parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getDeletedKeysCount());
    assertEquals(0, actualParseDelimitedFromResult.getScopeValue());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getValuesCount());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdMSB());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(AttributeScopeProto.CLIENT_SCOPE, actualParseDelimitedFromResult.getScope());
    assertFalse(actualParseDelimitedFromResult.getDeleted());
    assertFalse(actualParseDelimitedFromResult.hasScope());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<AttributeKey> deletedKeysList = actualParseDelimitedFromResult.getDeletedKeysList();
    assertTrue(deletedKeysList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(deletedKeysList, actualParseDelimitedFromResult.getDeletedKeysOrBuilderList());
    assertSame(deletedKeysList, actualParseDelimitedFromResult.getValuesList());
    assertSame(deletedKeysList, actualParseDelimitedFromResult.getValuesOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

