  /**
   * Test DeviceCredentialsProto {@link DeviceCredentialsProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link DeviceCredentialsProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test DeviceCredentialsProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"DeviceCredentialsProto DeviceCredentialsProto.parseDelimitedFrom(InputStream)"})
  void testDeviceCredentialsProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    DeviceCredentialsProto actualParseDelimitedFromResult = DeviceCredentialsProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getCredentialsId());
    assertEquals("", actualParseDelimitedFromResult.getCredentialsValue());
    assertEquals(0, actualParseDelimitedFromResult.getCredentialsTypeValue());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getCreatedTime());
    assertEquals(0L, actualParseDelimitedFromResult.getCredentialsIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getCredentialsIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getVersion());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(CredentialsType.ACCESS_TOKEN, actualParseDelimitedFromResult.getCredentialsType());
    assertFalse(actualParseDelimitedFromResult.hasCredentialsValue());
    assertFalse(actualParseDelimitedFromResult.hasVersion());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

