  /**
   * Test DeviceInfoProto {@link DeviceInfoProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link DeviceInfoProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test DeviceInfoProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"DeviceInfoProto DeviceInfoProto.parseDelimitedFrom(InputStream)"})
  void testDeviceInfoProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    DeviceInfoProto actualParseDelimitedFromResult = DeviceInfoProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getAdditionalInfo());
    assertEquals("", actualParseDelimitedFromResult.getDeviceName());
    assertEquals("", actualParseDelimitedFromResult.getDeviceType());
    assertEquals("", actualParseDelimitedFromResult.getPowerMode());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getCustomerIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getCustomerIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceProfileIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceProfileIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getEdrxCycle());
    assertEquals(0L, actualParseDelimitedFromResult.getPagingTransmissionWindow());
    assertEquals(0L, actualParseDelimitedFromResult.getPsmActivityTimer());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdMSB());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getIsGateway());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

