  /**
   * Test DeviceProto {@link DeviceProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link DeviceProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test DeviceProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"DeviceProto DeviceProto.parseDelimitedFrom(InputStream)"})
  void testDeviceProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    DeviceProto actualParseDelimitedFromResult = DeviceProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getAdditionalInfo());
    assertEquals("", actualParseDelimitedFromResult.getDeviceLabel());
    assertEquals("", actualParseDelimitedFromResult.getDeviceName());
    assertEquals("", actualParseDelimitedFromResult.getDeviceType());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getCreatedTime());
    assertEquals(0L, actualParseDelimitedFromResult.getCustomerIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getCustomerIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceProfileIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getDeviceProfileIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getExternalIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getExternalIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getFirmwareIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getFirmwareIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getSoftwareIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getSoftwareIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getVersion());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.hasAdditionalInfo());
    assertFalse(actualParseDelimitedFromResult.hasCustomerIdLSB());
    assertFalse(actualParseDelimitedFromResult.hasCustomerIdMSB());
    assertFalse(actualParseDelimitedFromResult.hasDeviceData());
    assertFalse(actualParseDelimitedFromResult.hasDeviceLabel());
    assertFalse(actualParseDelimitedFromResult.hasExternalIdLSB());
    assertFalse(actualParseDelimitedFromResult.hasExternalIdMSB());
    assertFalse(actualParseDelimitedFromResult.hasFirmwareIdLSB());
    assertFalse(actualParseDelimitedFromResult.hasFirmwareIdMSB());
    assertFalse(actualParseDelimitedFromResult.hasSoftwareIdLSB());
    assertFalse(actualParseDelimitedFromResult.hasSoftwareIdMSB());
    assertFalse(actualParseDelimitedFromResult.hasVersion());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

