  /**
   * Test EdgeHighPriorityMsgProto {@link EdgeHighPriorityMsgProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link EdgeHighPriorityMsgProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test EdgeHighPriorityMsgProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"EdgeHighPriorityMsgProto EdgeHighPriorityMsgProto.parseDelimitedFrom(InputStream)"})
  void testEdgeHighPriorityMsgProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    EdgeHighPriorityMsgProto actualParseDelimitedFromResult = EdgeHighPriorityMsgProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getAction());
    assertEquals("", actualParseDelimitedFromResult.getBody());
    assertEquals("", actualParseDelimitedFromResult.getType());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getEdgeIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getEdgeIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getEntityIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getEntityIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdMSB());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.hasBody());
    assertFalse(actualParseDelimitedFromResult.hasEdgeIdLSB());
    assertFalse(actualParseDelimitedFromResult.hasEdgeIdMSB());
    assertFalse(actualParseDelimitedFromResult.hasEntityIdLSB());
    assertFalse(actualParseDelimitedFromResult.hasEntityIdMSB());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

