  /**
   * Test EntityContentResponseMsg {@link EntityContentResponseMsg#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link EntityContentResponseMsg#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test EntityContentResponseMsg parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"EntityContentResponseMsg EntityContentResponseMsg.parseDelimitedFrom(InputStream)"})
  void testEntityContentResponseMsgParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    EntityContentResponseMsg actualParseDelimitedFromResult = EntityContentResponseMsg.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getData());
    assertEquals(0, actualParseDelimitedFromResult.getChunkIndex());
    assertEquals(0, actualParseDelimitedFromResult.getChunksCount());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

