  /**
   * Test GetAttributeRequestMsg {@link GetAttributeRequestMsg#getSharedAttributeNamesList()}.
   * <p>
   * Method under test: {@link GetAttributeRequestMsg#getSharedAttributeNamesList()}
   */
  @Test
  @DisplayName("Test GetAttributeRequestMsg getSharedAttributeNamesList()")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"ProtocolStringList GetAttributeRequestMsg.getSharedAttributeNamesList()"})
  void testGetAttributeRequestMsgGetSharedAttributeNamesList() {
    // Arrange
    GetAttributeRequestMsg defaultInstance = GetAttributeRequestMsg.getDefaultInstance();

    // Act
    ProtocolStringList actualSharedAttributeNamesList = defaultInstance.getSharedAttributeNamesList();

    // Assert
    assertTrue(actualSharedAttributeNamesList.isEmpty());
    LazyStringList lazyStringList = ((LazyStringArrayList) actualSharedAttributeNamesList).EMPTY;
    Descriptor descriptorForType = defaultInstance.getDescriptorForType();
    DescriptorProto toProtoResult = descriptorForType.toProto();
    DescriptorProto defaultInstanceForType = toProtoResult.getDefaultInstanceForType();
    assertEquals(lazyStringList, defaultInstanceForType.findInitializationErrors());
    Descriptor descriptorForType2 = toProtoResult.getDescriptorForType();
    assertEquals(lazyStringList, descriptorForType2.getEnumTypes());
    assertEquals(lazyStringList, descriptorForType2.getExtensions());
    assertEquals(lazyStringList, descriptorForType2.getOneofs());
    assertEquals(lazyStringList, descriptorForType2.getRealOneofs());
    assertSame(lazyStringList, defaultInstanceForType.getReservedNameList());
    assertSame(lazyStringList, toProtoResult.getReservedNameList());
    assertSame(lazyStringList, descriptorForType.getFile().toProto().getDependencyList());
    assertSame(lazyStringList, defaultInstance.getClientAttributeNamesList());
    assertSame(lazyStringList, actualSharedAttributeNamesList);
  }

