  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"GetAttributeResponseMsg GetAttributeResponseMsg.parseDelimitedFrom(InputStream)"})
  void testGetAttributeResponseMsgParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    GetAttributeResponseMsg actualParseDelimitedFromResult = GetAttributeResponseMsg.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getError());
    assertEquals(0, actualParseDelimitedFromResult.getClientAttributeListCount());
    assertEquals(0, actualParseDelimitedFromResult.getRequestId());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSharedAttributeListCount());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getIsMultipleAttributesRequest());
    assertFalse(actualParseDelimitedFromResult.getSharedStateMsg());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<TsKvProto> clientAttributeListList = actualParseDelimitedFromResult.getClientAttributeListList();
    assertTrue(clientAttributeListList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(clientAttributeListList, actualParseDelimitedFromResult.getClientAttributeListOrBuilderList());
    assertSame(clientAttributeListList, actualParseDelimitedFromResult.getSharedAttributeListList());
    assertSame(clientAttributeListList, actualParseDelimitedFromResult.getSharedAttributeListOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

