  /**
   * Test ImageCacheKeyProto {@link ImageCacheKeyProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link ImageCacheKeyProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test ImageCacheKeyProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"ImageCacheKeyProto ImageCacheKeyProto.parseDelimitedFrom(InputStream)"})
  void testImageCacheKeyProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    ImageCacheKeyProto actualParseDelimitedFromResult = ImageCacheKeyProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getPublicResourceKey());
    assertEquals("", actualParseDelimitedFromResult.getResourceKey());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.hasPublicResourceKey());
    assertFalse(actualParseDelimitedFromResult.hasResourceKey());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

