  void testListVersionsResponseMsgParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    ListVersionsResponseMsg actualParseDelimitedFromResult = ListVersionsResponseMsg.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getTotalPages());
    assertEquals(0, actualParseDelimitedFromResult.getVersionsCount());
    assertEquals(0L, actualParseDelimitedFromResult.getTotalElements());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getHasNext());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<EntityVersionProto> versionsList = actualParseDelimitedFromResult.getVersionsList();
    assertTrue(versionsList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(versionsList, actualParseDelimitedFromResult.getVersionsOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

