  @Test
  @DisplayName("Test QueueUpdateMsg parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"QueueUpdateMsg QueueUpdateMsg.parseDelimitedFrom(InputStream)"})
  void testQueueUpdateMsgParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    QueueUpdateMsg actualParseDelimitedFromResult = QueueUpdateMsg.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getQueueName());
    assertEquals("", actualParseDelimitedFromResult.getQueueTopic());
    assertEquals(0, actualParseDelimitedFromResult.getPartitions());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getQueueIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getQueueIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdMSB());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getDuplicateMsgToAllPartitions());
    assertFalse(actualParseDelimitedFromResult.hasDuplicateMsgToAllPartitions());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

