  /**
   * Test RepositorySettingsProto {@link RepositorySettingsProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link RepositorySettingsProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test RepositorySettingsProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"RepositorySettingsProto RepositorySettingsProto.parseDelimitedFrom(InputStream)"})
  void testRepositorySettingsProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    RepositorySettingsProto actualParseDelimitedFromResult = RepositorySettingsProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getAuthMethod());
    assertEquals("", actualParseDelimitedFromResult.getDefaultBranch());
    assertEquals("", actualParseDelimitedFromResult.getPassword());
    assertEquals("", actualParseDelimitedFromResult.getPrivateKey());
    assertEquals("", actualParseDelimitedFromResult.getPrivateKeyFileName());
    assertEquals("", actualParseDelimitedFromResult.getPrivateKeyPassword());
    assertEquals("", actualParseDelimitedFromResult.getRepositoryUri());
    assertEquals("", actualParseDelimitedFromResult.getUsername());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getLocalOnly());
    assertFalse(actualParseDelimitedFromResult.getReadOnly());
    assertFalse(actualParseDelimitedFromResult.getShowMergeCommits());
    assertFalse(actualParseDelimitedFromResult.hasDefaultBranch());
    assertFalse(actualParseDelimitedFromResult.hasPassword());
    assertFalse(actualParseDelimitedFromResult.hasPrivateKey());
    assertFalse(actualParseDelimitedFromResult.hasPrivateKeyFileName());
    assertFalse(actualParseDelimitedFromResult.hasPrivateKeyPassword());
    assertFalse(actualParseDelimitedFromResult.hasUsername());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

