  @MethodsUnderTest({"ServiceInfo ServiceInfo.parseDelimitedFrom(InputStream)"})
  void testServiceInfoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    ServiceInfo actualParseDelimitedFromResult = ServiceInfo.parseDelimitedFrom(input);

    // Assert
    UnknownFieldSet unknownFields = actualParseDelimitedFromResult.getUnknownFields();
    assertEquals(0, unknownFields.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(5, actualParseDelimitedFromResult.getDescriptorForType().getFields().size());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    SystemInfoProto systemInfo = actualParseDelimitedFromResult.getSystemInfo();
    assertSame(unknownFields, systemInfo.getUnknownFields());
    assertSame(unknownFields, unknownFields.getDefaultInstanceForType());
    ProtocolStringList assignedTenantProfilesList = actualParseDelimitedFromResult.getAssignedTenantProfilesList();
    assertSame(assignedTenantProfilesList, actualParseDelimitedFromResult.getServiceTypesList());
    assertSame(assignedTenantProfilesList, actualParseDelimitedFromResult.getTransportsList());
    assertSame(systemInfo, actualParseDelimitedFromResult.getSystemInfoOrBuilder());
    assertSame(systemInfo, systemInfo.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

