  /**
   * Test SubscribeToAttributeUpdatesMsg {@link SubscribeToAttributeUpdatesMsg#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link SubscribeToAttributeUpdatesMsg#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test SubscribeToAttributeUpdatesMsg parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"SubscribeToAttributeUpdatesMsg SubscribeToAttributeUpdatesMsg.parseDelimitedFrom(InputStream)"})
  void testSubscribeToAttributeUpdatesMsgParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    SubscribeToAttributeUpdatesMsg actualParseDelimitedFromResult = SubscribeToAttributeUpdatesMsg
        .parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSessionTypeValue());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(SessionType.SYNC, actualParseDelimitedFromResult.getSessionType());
    assertFalse(actualParseDelimitedFromResult.getUnsubscribe());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

