    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    TbAttributeDeleteProto actualParseDelimitedFromResult = TbAttributeDeleteProto.parseDelimitedFrom(input);

