  /**
   * Test TbEntitySubEventProto {@link TbEntitySubEventProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link TbEntitySubEventProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test TbEntitySubEventProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"TbEntitySubEventProto TbEntitySubEventProto.parseDelimitedFrom(InputStream)"})
  void testTbEntitySubEventProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    TbEntitySubEventProto actualParseDelimitedFromResult = TbEntitySubEventProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getEntityType());
    assertEquals("", actualParseDelimitedFromResult.getServiceId());
    assertEquals("", actualParseDelimitedFromResult.getType());
    assertEquals(0, actualParseDelimitedFromResult.getAttrKeysCount());
    assertEquals(0, actualParseDelimitedFromResult.getSeqNumber());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getTsKeysCount());
    assertEquals(0L, actualParseDelimitedFromResult.getEntityIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getEntityIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdMSB());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getAlarms());
    assertFalse(actualParseDelimitedFromResult.getAttrAllKeys());
    assertFalse(actualParseDelimitedFromResult.getNotifications());
    assertFalse(actualParseDelimitedFromResult.getTsAllKeys());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    ProtocolStringList attrKeysList = actualParseDelimitedFromResult.getAttrKeysList();
    assertTrue(attrKeysList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(attrKeysList, actualParseDelimitedFromResult.getTsKeysList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

