  /**
   * Test TbResourceProto {@link TbResourceProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link TbResourceProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test TbResourceProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"TbResourceProto TbResourceProto.parseDelimitedFrom(InputStream)"})
  void testTbResourceProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    TbResourceProto actualParseDelimitedFromResult = TbResourceProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getEtag());
    assertEquals("", actualParseDelimitedFromResult.getFileName());
    assertEquals("", actualParseDelimitedFromResult.getPublicResourceKey());
    assertEquals("", actualParseDelimitedFromResult.getResourceDescriptor());
    assertEquals("", actualParseDelimitedFromResult.getResourceKey());
    assertEquals("", actualParseDelimitedFromResult.getResourceSubType());
    assertEquals("", actualParseDelimitedFromResult.getResourceType());
    assertEquals("", actualParseDelimitedFromResult.getSearchText());
    assertEquals("", actualParseDelimitedFromResult.getTitle());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getCreatedTime());
    assertEquals(0L, actualParseDelimitedFromResult.getExternalIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getExternalIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getResourceIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getResourceIdMSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantIdMSB());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getIsPublic());
    assertFalse(actualParseDelimitedFromResult.hasData());
    assertFalse(actualParseDelimitedFromResult.hasEtag());
    assertFalse(actualParseDelimitedFromResult.hasExternalIdLSB());
    assertFalse(actualParseDelimitedFromResult.hasExternalIdMSB());
    assertFalse(actualParseDelimitedFromResult.hasPreview());
    assertFalse(actualParseDelimitedFromResult.hasPublicResourceKey());
    assertFalse(actualParseDelimitedFromResult.hasResourceDescriptor());
    assertFalse(actualParseDelimitedFromResult.hasResourceSubType());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

