  /**
   * Test TenantProfileProto {@link TenantProfileProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link TenantProfileProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test TenantProfileProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"TenantProfileProto TenantProfileProto.parseDelimitedFrom(InputStream)"})
  void testTenantProfileProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    TenantProfileProto actualParseDelimitedFromResult = TenantProfileProto.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getDescription());
    assertEquals("", actualParseDelimitedFromResult.getName());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getCreatedTime());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantProfileIdLSB());
    assertEquals(0L, actualParseDelimitedFromResult.getTenantProfileIdMSB());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getIsDefault());
    assertFalse(actualParseDelimitedFromResult.getIsolatedTbRuleEngine());
    assertFalse(actualParseDelimitedFromResult.hasDescription());
    assertFalse(actualParseDelimitedFromResult.hasProfileData());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

