  /**
   * Test TransportApiRequestMsg {@link TransportApiRequestMsg#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link TransportApiRequestMsg#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test TransportApiRequestMsg parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"TransportApiRequestMsg TransportApiRequestMsg.parseDelimitedFrom(InputStream)"})
  void testTransportApiRequestMsgParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{2, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act and Assert
    assertEquals(2, TransportApiRequestMsg.parseDelimitedFrom(input).getSerializedSize());
    byte[] byteArray = new byte[5];
    assertEquals(5, input.read(byteArray));
    assertArrayEquals("XAXAX".getBytes("UTF-8"), byteArray);
  }

