  /**
   * Test TsKvProto {@link TsKvProto#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link TsKvProto#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test TsKvProto parseDelimitedFrom(InputStream) with 'input'")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"TsKvProto TsKvProto.parseDelimitedFrom(InputStream)"})
  void testTsKvProtoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{2, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    TsKvProto actualParseDelimitedFromResult = TsKvProto.parseDelimitedFrom(input);

    // Assert
    assertEquals(2, actualParseDelimitedFromResult.getUnknownFields().getSerializedSize());
    assertEquals(2, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[5];
    assertEquals(5, input.read(byteArray));
    TsKvProto defaultInstanceForType = actualParseDelimitedFromResult.getDefaultInstanceForType();
    assertSame(defaultInstanceForType.getDefaultInstanceForType(), defaultInstanceForType.getDefaultInstanceForType());
    KeyValueProto kv = actualParseDelimitedFromResult.getKv();
    assertSame(kv, kv.getDefaultInstanceForType());
    assertSame(kv, defaultInstanceForType.getKv());
    assertSame(kv, defaultInstanceForType.getKvOrBuilder());
    assertSame(kv, actualParseDelimitedFromResult.getKvOrBuilder());
    assertArrayEquals("XAXAX".getBytes("UTF-8"), byteArray);
  }

