  @Test
  @DisplayName("Test TsValueProto getJsonVBytes()")
  @Tag("MaintainedByDiffblue")
  @MethodsUnderTest({"ByteString TsValueProto.getJsonVBytes()"})
  void testTsValueProtoGetJsonVBytes() {
    // Arrange
    TsValueProto defaultInstance = TsValueProto.getDefaultInstance();

    // Act
    ByteString actualJsonVBytes = defaultInstance.getJsonVBytes();

    // Assert
    ByteString byteString = actualJsonVBytes.EMPTY;
    Descriptor descriptorForType = defaultInstance.getDescriptorForType();
    assertEquals(byteString, descriptorForType.toProto().getDefaultInstanceForType().getNameBytes());
    FileOptions options = descriptorForType.getFile().getOptions();
    assertEquals(byteString, options.getCsharpNamespaceBytes());
    assertEquals(byteString, options.getGoPackageBytes());
    assertEquals(byteString, options.getObjcClassPrefixBytes());
    assertEquals(byteString, options.getPhpClassPrefixBytes());
    assertEquals(byteString, options.getPhpMetadataNamespaceBytes());
    assertEquals(byteString, options.getPhpNamespaceBytes());
    assertEquals(byteString, options.getRubyPackageBytes());
    assertEquals(byteString, options.getSwiftPrefixBytes());
    assertEquals(byteString, actualJsonVBytes);
    assertEquals(byteString, defaultInstance.getStringVBytes());
  }

